#define main previous_dp4a_main
#include "dp4a_benchmark.cu"
#undef main
#include <cublas_v2.h>
#include <algorithm>
#include <fstream>
#include <iostream>
#include <cstring>
#include <thread>
#include <atomic>
#include <limits>
#include <utility>
#include <dlfcn.h>
#include <array>
#include <cmath>
#include <string>
#define BLAS(call) do { auto s=(call); if(s!=CUBLAS_STATUS_SUCCESS) { fprintf(stderr,"cuBLAS error %d\n",int(s)); exit(1); } } while(0)
static int mismatch(const std::vector<int32_t>& a,const std::vector<int32_t>& b) { int n=0; for(size_t i=0;i<a.size();++i) n+=(a[i]!=b[i]); return n;
} int main() {
    void* lib=dlopen("libnvidia-ml.so.1",RTLD_LAZY); if(!lib) lib=dlopen("/usr/lib/wsl/lib/libnvidia-ml.so.1",RTLD_LAZY);
    using Init=int(*)(); using Handle=int(*)(unsigned,void**); using Power=int(*)(void*,unsigned*);
    auto init=lib?reinterpret_cast<Init>(dlsym(lib,"nvmlInit_v2")):nullptr; auto device=lib?reinterpret_cast<Handle>(dlsym(lib,"nvmlDeviceGetHandleByIndex_v2")):nullptr; auto power=lib?reinterpret_cast<Power>(dlsym(lib,"nvmlDeviceGetPowerUsage")):nullptr;
    void* gpu_handle=nullptr; bool sensor=!getenv("DISABLE_POWER")&&init&&device&&power&&init()==0&&device(0,&gpu_handle)==0;
    auto ticks=[](){return std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();};
    cudaDeviceProp gpu; CHECK_CUDA(cudaGetDeviceProperties(&gpu,0)); int version=0; BLAS(cublasGetVersion(nullptr,&version)); const char* dir=getenv("PIPELINE_RESULTS"); if(!dir) { std::cerr<<"Set PIPELINE_RESULTS to an existing directory\n"; return 3; } std::string root(dir);
    std::ofstream raw(root+"/raw.csv"), power_raw(root+"/power.csv"), latency_raw(root+"/latency.csv"), report(root+"/REPORT.md"); if(!raw||!power_raw||!latency_raw||!report) return 3; raw.precision(12); power_raw.precision(12); latency_raw.precision(12);
    raw<<"batch,mode,round,completed_requests,seconds,requests_s,inputs_s,amortized_ms,latency_p50_ms,latency_p95_ms,latency_samples,gpu_mean_w,gpu_est_j,gpu_est_mj_per_request,power_samples,power_coverage,pinned_host_bytes,device_tensor_bytes,checked_requests,mismatches,stale_control_passed,injected_control_passed\n"; power_raw<<"batch,mode,round,steady_s,power_w\n"; latency_raw<<"batch,mode,round,request_id,input_bank,host_observed_ms\n";
    const char* names[]={"serial_pageable","serial_pinned","async_1stream","async_2streams","async_2streams_serialized"};
    report<<"# Two-Stream Pipeline Experiment\n\nGPU: "<<gpu.name<<"; cuBLAS: "<<version<<"; CUDA compiler: "<<__CUDACC_VER_MAJOR__<<'.'<<__CUDACC_VER_MINOR__<<'.'<<__CUDACC_VER_BUILD__<<"; copy engines: "<<gpu.asyncEngineCount<<"; concurrent kernels: "<<gpu.concurrentKernels<<".\n\nSeed 12345; int8 [-8,7], int32 outputs, four distinct precomputed input banks, 4096 inputs and 512 outputs per vector. Weights stay GPU-resident. Allocation, CPU reference and input preparation excluded. Five trials with rotated method order, 1-second warm-up, >=5 seconds timed including final drain.\n\nThroughput counts completed requests; each request contains Batch input vectors. Latency is host-observed submission-to-completion, sampled every 31st request under closed-loop saturation, not amortized throughput or open-loop service latency. Full correctness checks before/after timing and on final buffers; timed requests are not all checked. Stale-output and injected-error controls must reject errors. No profiling proof of kernel/copy overlap.\n\nGPU board energy is estimated from ~100ms power samples, not CPU or wall energy; other GPU activity contributes. nan means unavailable/poor coverage. raw.csv records exact buffer allocation bytes excluding library/context/allocator overhead. DISABLE_POWER=1 disables queries for a telemetry-overhead control.\n\nMedian of five trials (latency quantiles are per-trial sampled statistics):\n\n| Batch | Mode | Completed requests/s | Host p50 ms | Host p95 ms | GPU mJ/request | Throughput vs best serial | Valid power trials |\n|---|---|---:|---:|---:|---:|---:|---:|\n";
    struct Slot { cudaStream_t stream=nullptr; cudaEvent_t event=nullptr; cublasHandle_t blas=nullptr; int8_t* dx=nullptr; int32_t *dy=nullptr,*hy=nullptr; std::vector<int32_t> page; uint64_t id=0; int bank=0; double submitted=0; bool pending=false; }; struct Latency { uint64_t id; int bank; double ms; };
    for(int batch:{1,16,128}) { const size_t xb=size_t(batch)*4096, count=size_t(batch)*512, yb=count*4, wb=size_t(512)*4096; std::mt19937 rng(12345); std::uniform_int_distribution<int> dist(-8,7); std::vector<int8_t> w(wb); for(auto& v:w) v=dist(rng); std::vector<std::vector<int8_t>> inputs(4,std::vector<int8_t>(xb)); std::vector<std::vector<int32_t>> expected(4,std::vector<int32_t>(count));
        for(int bank=0;bank<4;++bank) { for(auto& v:inputs[bank]) v=dist(rng); cpu_ref(inputs[bank],w,expected[bank],batch,512,4096); } int8_t* dw=nullptr; CHECK_CUDA(cudaMalloc(&dw,wb)); CHECK_CUDA(cudaMemcpy(dw,w.data(),wb,cudaMemcpyHostToDevice)); CHECK_CUDA(cudaDeviceSynchronize()); std::vector<std::array<double,4>> stats[5];
        for(int round=0;round<5;++round) for(int order=0;order<5;++order) { int kind=(order+round)%5, depth=kind>=3?2:1; bool pinned=kind!=0, asynchronous=kind>=2; int8_t* hx[4]; std::vector<Slot> slots(depth);
            for(int bank=0;bank<4;++bank) { hx[bank]=inputs[bank].data(); if(pinned) { CHECK_CUDA(cudaMallocHost(&hx[bank],xb)); std::memcpy(hx[bank],inputs[bank].data(),xb); } }
            for(auto& z:slots) { CHECK_CUDA(cudaMalloc(&z.dx,xb)); CHECK_CUDA(cudaMalloc(&z.dy,yb)); if(pinned) CHECK_CUDA(cudaMallocHost(&z.hy,yb)); else { z.page.resize(count); z.hy=z.page.data(); } if(asynchronous) { CHECK_CUDA(cudaStreamCreateWithFlags(&z.stream,cudaStreamNonBlocking)); CHECK_CUDA(cudaEventCreateWithFlags(&z.event,cudaEventDisableTiming)); } BLAS(cublasCreate(&z.blas)); BLAS(cublasSetStream(z.blas,z.stream)); } CHECK_CUDA(cudaDeviceSynchronize());
            uint64_t completed=0,checked=0; std::vector<Latency> latencies; latencies.reserve(262144);
            auto errors=[&](const Slot& z) { int n=0; for(size_t i=0;i<count;++i) n+=(z.hy[i]!=expected[z.bank][i]); return n; };
            auto finish=[&](Slot& z,bool check,bool collect) { if(!z.pending) return; if(asynchronous) CHECK_CUDA(cudaEventSynchronize(z.event)); double ms=(ticks()-z.submitted)*1000; if(check) { ++checked; if(errors(z)) { std::cerr<<"Correctness failed: batch="<<batch<<" mode="<<names[kind]<<" bank="<<z.bank<<"\n"; exit(2); } } if(collect&&z.id%31==0) latencies.push_back({z.id,z.bank,ms}); ++completed; z.pending=false; };
            auto submit=[&](Slot& z,uint64_t id) { if(z.pending) { std::cerr<<"Unsafe buffer reuse\n"; exit(2); } z.id=id; z.bank=id%4; z.submitted=ticks(); z.pending=true;
                if(asynchronous) CHECK_CUDA(cudaMemcpyAsync(z.dx,hx[z.bank],xb,cudaMemcpyHostToDevice,z.stream)); else CHECK_CUDA(cudaMemcpy(z.dx,hx[z.bank],xb,cudaMemcpyHostToDevice));
                int32_t alpha=1,beta=0; BLAS(cublasGemmEx(z.blas,CUBLAS_OP_T,CUBLAS_OP_N,512,batch,4096,&alpha,dw,CUDA_R_8I,4096,z.dx,CUDA_R_8I,4096,&beta,z.dy,CUDA_R_32I,512,CUBLAS_COMPUTE_32I,CUBLAS_GEMM_DEFAULT)); CHECK_CUDA(cudaGetLastError());
                if(asynchronous) { CHECK_CUDA(cudaMemcpyAsync(z.hy,z.dy,yb,cudaMemcpyDeviceToHost,z.stream)); CHECK_CUDA(cudaEventRecord(z.event,z.stream)); } else CHECK_CUDA(cudaMemcpy(z.hy,z.dy,yb,cudaMemcpyDeviceToHost)); };
            auto step=[&](uint64_t id,bool check,bool collect) { auto& z=slots[id%depth]; finish(z,check,collect); submit(z,id); if(kind!=3) finish(z,check,collect); };
            auto drain=[&](uint64_t n,bool check,bool collect) { for(uint64_t i=n>uint64_t(depth)?n-depth:0;i<n;++i) finish(slots[i%depth],check,collect); };
            step(0,true,false); drain(1,true,false); auto& control=slots[0]; control.bank=1; if(errors(control)==0) { std::cerr<<"Stale-output control failed\n"; exit(2); } control.bank=0; control.hy[0]^=1; if(errors(control)!=1) { std::cerr<<"Injected-error control failed\n"; exit(2); } control.hy[0]^=1; checked=0;
            auto validate=[&]() { for(uint64_t i=0;i<64;++i) step(i,true,false); drain(64,true,false); }; validate(); double warm=ticks(); uint64_t n=0; do { step(n++,false,false); } while(ticks()-warm<1); drain(n,false,false); completed=0;
            std::atomic<bool> stop(false); std::vector<std::pair<double,double>> samples; std::thread monitor([&]() { while(!stop.load()) { unsigned mw=0; double before=ticks(); int status=sensor?power(gpu_handle,&mw):-1; double after=ticks(); if(status==0&&mw>0) samples.emplace_back((before+after)/2,mw/1000.0); std::this_thread::sleep_for(std::chrono::milliseconds(100)); } });
            n=0; double t0=ticks(); do { step(n++,false,true); } while(ticks()-t0<5); drain(n,false,true); double t1=ticks(), seconds=t1-t0; stop=true; monitor.join(); if(completed!=n) { std::cerr<<"Completion count failed\n"; exit(2); } for(auto& z:slots) { ++checked; if(errors(z)) { std::cerr<<"Final buffer correctness failed\n"; exit(2); } } validate();
            double integral=0,span=0,gap=0; int points=0; std::pair<double,double> prev; for(auto p:samples) { power_raw<<batch<<','<<names[kind]<<','<<round<<','<<p.first<<','<<p.second<<'\n'; if(p.first<t0||p.first>t1) continue; if(points) { double dt=p.first-prev.first; integral+=dt*(prev.second+p.second)/2; span+=dt; gap=std::max(gap,dt); } prev=p; ++points; } double coverage=span/seconds, mean_w=std::numeric_limits<double>::quiet_NaN(); if(points>=20&&coverage>=0.9&&gap<=0.5) mean_w=integral/span; double mj=mean_w*seconds*1000/n;
            std::vector<double> values; values.reserve(latencies.size()); for(auto p:latencies) { latency_raw<<batch<<','<<names[kind]<<','<<round<<','<<p.id<<','<<p.bank<<','<<p.ms<<'\n'; values.push_back(p.ms); } std::sort(values.begin(),values.end()); double p50=values[(values.size()-1)/2],p95=values[size_t(0.95*(values.size()-1))], rate=n/seconds; stats[kind].push_back({rate,p50,p95,mj});
            raw<<batch<<','<<names[kind]<<','<<round<<','<<n<<','<<seconds<<','<<rate<<','<<batch*rate<<','<<1000/rate<<','<<p50<<','<<p95<<','<<values.size()<<','<<mean_w<<','<<mean_w*seconds<<','<<mj<<','<<points<<','<<coverage<<','<<(pinned?4*xb+depth*yb:0)<<','<<wb+depth*(xb+yb)<<','<<checked<<",0,1,1\n"; raw.flush(); power_raw.flush(); latency_raw.flush(); std::cout<<"batch="<<batch<<" "<<names[kind]<<" trial="<<round+1<<"/5 completed="<<n<<std::endl;
            for(auto& z:slots) { BLAS(cublasDestroy(z.blas)); if(asynchronous) { CHECK_CUDA(cudaEventDestroy(z.event)); CHECK_CUDA(cudaStreamDestroy(z.stream)); } CHECK_CUDA(cudaFree(z.dx)); CHECK_CUDA(cudaFree(z.dy)); if(pinned) CHECK_CUDA(cudaFreeHost(z.hy)); } if(pinned) for(auto h:hx) CHECK_CUDA(cudaFreeHost(h));
        }
        auto median=[&](int kind,int field) { std::vector<double> v; for(auto r:stats[kind]) if(std::isfinite(r[field])) v.push_back(r[field]); if(v.empty()) return std::numeric_limits<double>::quiet_NaN(); std::sort(v.begin(),v.end()); return v[v.size()/2]; }; double best=std::max(median(0,0),median(1,0)); for(int kind=0;kind<5;++kind) { int valid=0; for(auto r:stats[kind]) valid+=std::isfinite(r[3]); report<<"| "<<batch<<" | "<<names[kind]<<" | "<<median(kind,0)<<" | "<<median(kind,1)<<" | "<<median(kind,2)<<" | "<<median(kind,3)<<" | "<<median(kind,0)/best<<"x | "<<valid<<"/5 |\n"; } report.flush(); CHECK_CUDA(cudaFree(dw));
    }
    report<<"\n## Reproduction\n\nFrom this result directory:\n\n```bash\n/usr/local/cuda-13.2/bin/nvcc -O3 -std=c++17 -arch=sm_75 pipeline_energy.cu -lcublas -ldl -Xcompiler -pthread -o pipeline_energy\nout=\"$PWD/rerun_$(date -u +%Y%m%dT%H%M%SZ)\"\nmkdir \"$out\"\nCUDA_VISIBLE_DEVICES=0 LD_LIBRARY_PATH=/usr/local/cuda-13.2/lib64${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH} PIPELINE_RESULTS=\"$out\" ./pipeline_energy\n```\n";
    report<<"\nAll validation passes and both negative correctness controls passed. Each cell validated 128 sequence requests plus final buffers. Outputs: raw.csv, power.csv, latency.csv; source snapshots included.\n"; std::cout<<"All correctness checks passed. Results: "<<root<<std::endl; return 0;
}
